Param(    [Parameter(Mandatory=$true)] [string]$stackName,    [Parameter(Mandatory=$true)] [string]$containerVersion,    [Parameter(Mandatory=$true)] [string]$cmsVersionParam,    [Parameter(Mandatory=$true)] [string]$pluginsLayerVersion,    [Parameter(Mandatory=$true)] [string]$otherPlugins,    [Parameter(Mandatory=$true)] [string]$vpcSecurityGroupId,    [Parameter(Mandatory=$true)] [string]$vpcSubnet1Id,    [Parameter(Mandatory=$true)] [string]$vpcSubnet2Id,    [Parameter(Mandatory=$true)] [string]$certificateArn,    [Parameter(Mandatory=$true)] [string]$domain,    [Parameter(Mandatory=$true)] [string]$emailUsername,    [Parameter(Mandatory=$true)] [string]$emailPassword,    [Parameter(Mandatory=$true)] [string]$emailHost,    [Parameter(Mandatory=$true)] [string]$emailPort,    [Parameter(Mandatory=$true)] [string]$emailSsl,    [Parameter(Mandatory=$true)] [string]$connectionString,    [Parameter(Mandatory=$true)] [string]$uploadsAccessKey,    [Parameter(Mandatory=$true)] [string]$uploadsSecretKey,    [Parameter(Mandatory=$true)] [string]$regionName)$cmsVersionParam = $cmsVersionParam.Replace("v", "")$cmsVersion = $cmsVersionParam.Replace(".", "-")$containerVersion = $containerVersion.Replace("v", "").Replace("-", ".")$stackNameLower = $stackName.ToLower() echo "Updating the ${stackName} stack"aws --region "${regionName}" cloudformation update-stack `--use-previous-template `--stack-name "${stackName}" `--capabilities "CAPABILITY_IAM" `--parameters `	ParameterKey=Domain,ParameterValue="${domain}"`	ParameterKey=OmegaLambdaContainerCodeUriBucket,ParameterValue="md-cms-awslambda-container"`	ParameterKey=OmegaLambdaContainerCodeUriKey,ParameterValue="container.awslambda.${containerVersion}"`	ParameterKey=StackName,ParameterValue="${stackNameLower}"`	ParameterKey=BillingGroup,ParameterValue="${stackNameLower}"`	ParameterKey=VpcSecurityGroupId,ParameterValue="${vpcSecurityGroupId}"`	ParameterKey=VpcSubnet1Id,ParameterValue="${vpcSubnet1Id}"`	ParameterKey=VpcSubnet2Id,ParameterValue="${vpcSubnet1Id}"`	ParameterKey=CloudFrontCertificateArn,ParameterValue="${certificateArn}"`	ParameterKey=OmegaCmsDataAccessPlugins,ParameterValue="'[ \`"MD.Tools.BaseDataAccess.Plugins.WebService.Core\`", \`"MD.Tools.BaseDataAccess.Plugins.MySql.Core\`" ]'"`	ParameterKey=OmegaCmsDataAccessPluginSettings,ParameterValue="'{\`"MD.Tools.BaseDataAccess.Plugins.MySql.Core\`": \`"${connectionString}\`", \`"MD.Tools.BaseDataAccess.Plugins.WebService.Core\`": \`"\`"}'"`	ParameterKey=OmegaCmsCorsOrigins,ParameterValue="'[\`"https://${domain}\`"]'"`	ParameterKey=OmegaCmsSessionDomain,ParameterValue="${domain}"`	ParameterKey=OmegaCmsSessionTimeout,ParameterValue="01:00:00"`	ParameterKey=OmegaCmsDefaultLcid,ParameterValue="2057"`	ParameterKey=EmailUsername,ParameterValue="${emailUsername}"`	ParameterKey=EmailPassword,ParameterValue="${emailPassword}"`	ParameterKey=EmailHost,ParameterValue="${emailHost}"`	ParameterKey=EmailPort,ParameterValue="${emailPort}"`	ParameterKey=EmailUseSsl,ParameterValue="${emailSsl}"`	ParameterKey=AdminStageName,ParameterValue="admin"`	ParameterKey=AdminWebAppPath,ParameterValue="/opt/MD.CMS.Administration.Core.AwsLambda/"`	ParameterKey=AdminAppReferencePath,ParameterValue="MD.CMS.Administration.Core.AwsLambda.dll.MD.CMS.Administration.Core.AwsLambda.AwsStartup"`	ParameterKey=AdminGatewayName,ParameterValue="MD-CMS-AwsLambda-CloudFormation-Core-Admin"`	ParameterKey=AdminMDCMSBusinessLogicCoreDefaultLcid,ParameterValue="2057"`	ParameterKey=AdminMDCMSBusinessLogicCoreGoogleApiTranslationKey,ParameterValue=""`	ParameterKey=AdminMDCMSBusinessLogicCoreGoogleMapsJsKey,ParameterValue=""`	ParameterKey=AdminMDToolsHelpersCoreProviderOptions,ParameterValue=""`	ParameterKey=AdminMDToolsHelpersCoreDefaultFileProvider,ParameterValue="1"`	ParameterKey=AdminMDToolsHelpersCoreVerboseLoggingReflectionEnabled,ParameterValue=""`	ParameterKey=AdminMDCMSAdministrationCorePluginsDirectory,ParameterValue="/opt/AwsLambdaPlugins/"`	ParameterKey=AdminMDCMSAdministrationCorePluginsFileProviderType,ParameterValue="1"`	ParameterKey=AdminBasePluginsLayer,ParameterValue="arn:aws:lambda:us-east-1:518606024901:layer:AwsLambdaPlugins:${pluginsLayerVersion}"`	ParameterKey=AdminProductLayer,ParameterValue="arn:aws:lambda:us-east-1:518606024901:layer:MD-CMS-Administration-Core-AwsLambda-v${cmsVersion}:1"`	ParameterKey=AdminOtherPlugins,ParameterValue="${otherPlugins}"`	ParameterKey=WebApiStageName,ParameterValue="ws"`	ParameterKey=WebApiWebAppPath,ParameterValue="/opt/MD.CMS.WebApi.Core.AwsLambda/"`	ParameterKey=WebApiAppReferencePath,ParameterValue="MD.CMS.WebApi.Core.AwsLambda.dll.MD.CMS.WebApi.Core.AwsLambda.AwsStartup"`	ParameterKey=WebApiGatewayName,ParameterValue="MD-CMS-AwsLambda-CloudFormation-Core-WebApi"`	ParameterKey=WebApiMDCMSBusinessLogicCoreRootAdminAccount,ParameterValue=""`	ParameterKey=WebApiMDCMSWebApiCorePluginsDirectory,ParameterValue="/opt/AwsLambdaPlugins/"`	ParameterKey=WebApiMDCMSWebApiCorePluginsFileProviderType,ParameterValue="1"`	ParameterKey=WebApiMDToolsBaseDataAccessPluginsCoreDataAccessPlugins,ParameterValue=""`	ParameterKey=WebApiMDToolsBaseDataAccessPluginsCoreDataAccessPluginSettings,ParameterValue=""`	ParameterKey=WebApiMDToolsBaseDataAccessPluginsCoreBaseDataAccessPluginsDirectory,ParameterValue="/opt/AwsLambdaPlugins/"`	ParameterKey=WebApiMDToolsBaseDataAccessPluginsCoreBaseDataAccessPluginsFileProviderType,ParameterValue="1"`	ParameterKey=WebApiMDToolsHelpersCoreProviderOptions,ParameterValue="'{ \`"AWSS3FileProvider\`": \`"   {\\\`"BucketName\\\`": \\\`"${stackNameLower}-admin-uploads\\\`", \\\`"AccessKey\\\`": \\\`"${uploadsAccessKey}\\\`", \\\`"SecretKey\\\`": \\\`"${uploadsSecretKey}\\\`", \\\`"RegionDisplayName\\\`": \\\`"${regionName}\\\`", \\\`"CacheFiles\\\`": false, \\\`"CacheLocation\\\`": \\\`"\\\`"}   \`" }'" `	ParameterKey=WebApiMDToolsHelpersCoreDefaultFileProvider,ParameterValue="1"`	ParameterKey=WebApiMDCMSWebApiCoreBaseApiPath,ParameterValue=""`	ParameterKey=WebApiMDCMSWebApiCoreBaseFolder,ParameterValue=""`	ParameterKey=WebApiApiTimeout,ParameterValue="30"`	ParameterKey=WebApiTraceLevel,ParameterValue="1"`	ParameterKey=WebApiMDToolsHelpersCoreVerboseLoggingReflectionEnabled,ParameterValue=""`	ParameterKey=WebApiBasePluginsLayer,ParameterValue="arn:aws:lambda:us-east-1:518606024901:layer:AwsLambdaPlugins:${pluginsLayerVersion}"`	ParameterKey=WebApiProductLayer,ParameterValue="arn:aws:lambda:us-east-1:518606024901:layer:MD-CMS-WebApi-Core-AwsLambda-v${cmsVersion}:1"`	ParameterKey=WebApiOtherPlugins,ParameterValue="${otherPlugins}"`	ParameterKey=WebApiSocketsOtherPlugins,ParameterValue="${otherPlugins}"`	ParameterKey=WebApiSocketsBasePluginsLayer,ParameterValue="arn:aws:lambda:us-east-1:518606024901:layer:AwsLambdaPlugins:${pluginsLayerVersion}"`	ParameterKey=WebApiSocketsProductLayer,ParameterValue="arn:aws:lambda:us-east-1:518606024901:layer:MD-CMS-WebApi-Sockets-Core-AwsLambda-v${cmsVersion}:1"`	ParameterKey=WebApiSocketsStageName,ParameterValue="ws-web-sockets"`	ParameterKey=WebApiSocketsWebAppPath,ParameterValue="/opt/MD.CMS.WebApi.Sockets.Core.AwsLambda/"`	ParameterKey=WebApiSocketsAppReferencePath,ParameterValue="MD.CMS.WebApi.Sockets.Core.AwsLambda.dll.MD.CMS.WebApi.Sockets.Core.AwsLambda.Functions"`	ParameterKey=WebApiSocketsGatewayName,ParameterValue="MD-CMS-AwsLambda-CloudFormation-Core-WebApi-Sockets"`	ParameterKey=WebApiSocketsMDCMSBusinessLogicCoreRootAdminAccount,ParameterValue=""`	ParameterKey=WebApiSocketsMDCMSWebApiCorePluginsDirectory,ParameterValue="/opt/AwsLambdaPlugins/"`	ParameterKey=WebApiSocketsMDCMSWebApiCorePluginsFileProviderType,ParameterValue="1"`	ParameterKey=WebApiSocketsMDToolsBaseDataAccessPluginsCoreDataAccessPlugins,ParameterValue=""`	ParameterKey=WebApiSocketsMDToolsBaseDataAccessPluginsCoreDataAccessPluginSettings,ParameterValue=""`	ParameterKey=WebApiSocketsMDToolsBaseDataAccessPluginsCoreBaseDataAccessPluginsDirectory,ParameterValue="/opt/AwsLambdaPlugins/"`	ParameterKey=WebApiSocketsMDToolsBaseDataAccessPluginsCoreBaseDataAccessPluginsFileProviderType,ParameterValue="1"`	ParameterKey=WebApiSocketsMDToolsHelpersCoreProviderOptions,ParameterValue=""`	ParameterKey=WebApiSocketsMDToolsHelpersCoreDefaultFileProvider,ParameterValue="1"`	ParameterKey=WebApiSocketsMDCMSWebApiCoreBaseApiPath,ParameterValue=""`	ParameterKey=WebApiSocketsApiTimeout,ParameterValue="30"`	ParameterKey=WebApiSocketsTraceLevel,ParameterValue="1"`	ParameterKey=WebApiSocketsMDToolsHelpersCoreVerboseLoggingReflectionEnabled,ParameterValue="false"`	ParameterKey=WebApiSocketsDebugMode,ParameterValue="false"echo "${stackName} stack updated!"echo "Transferring static assets for the ${stackName} stack"aws s3 cp "s3://omega-cms-admin/assets/assets.${cmsVersionParam}" "s3://${stackNameLower}-admin-assets" --exclude "js/ext/*" --exclude "js/gridstack/*" --exclude "scripts/businessLogic*" --exclude "scripts/app/*.js" --exclude "scripts/app/*.scss" --exclude "scripts/.scannerwork/*" --exclude "scripts/plugins/tinymce-dist/node_modules/*" --recursive --quietecho "${stackName} static assets transferred!"echo "Clearing cache for the ${stackName} stack"$output = aws cloudformation describe-stack-resources --stack-name $stackName | ConvertFrom-Json$cloudFormationObj = $output.StackResources | where { $_.ResourceType -eq "AWS::CloudFront::Distribution" }$queitResult = aws cloudfront create-invalidation --distribution-id $cloudFormationObj.PhysicalResourceId --paths "/*"echo "${stackName} cache cleared!"